page_settings.custom_css:
/* =====================================================================
   Laoret × tcworld 2026 — custom CSS for the Elementor Pro build
   Paste once into: Site Settings → Custom CSS  (or a page's Page Settings → Custom CSS)
   Every rule targets a CSS class you add in  Advanced → CSS Classes  on a container/widget.
   ===================================================================== */

:root{
  --lt-navy:#0B233F; --lt-teal:#00A2AE; --lt-teal-d:#008B96; --lt-icon:#1EC0CC; --lt-cyan:#00C0CF;
  --lt-coral:#F05A5C; --lt-dark:#000915; --lt-aqua:#E1F6F6; --lt-line:#E3EAF0; --lt-soft:#F6F9FB;
}

/* ---------- Hero info bar (container class: lt-event-bar) ----------
   Sits half over the hero: give the container Margin Top = -60px and Z-Index = 2 in Elementor. */
.lt-event-bar{box-shadow:0 10px 30px rgba(11,35,63,.07)}

/* ---------- WHY MEET: illustrated cards ----------
   Card container class: lt-why-card   (+ lt-acc-coral / lt-acc-navy on cards 2,5 / 3,6)
   Image widget class:  lt-why-visual */
.lt-why-card{--acc:var(--lt-teal);position:relative;overflow:hidden;
  transition:transform .35s cubic-bezier(.2,.7,.2,1),box-shadow .35s,border-color .35s}
.lt-why-card.lt-acc-coral{--acc:var(--lt-coral)}
.lt-why-card.lt-acc-navy{--acc:var(--lt-navy)}
.lt-why-card::after{content:"";position:absolute;left:0;top:0;height:4px;width:0;background:var(--acc);
  transition:width .5s cubic-bezier(.2,.7,.2,1);z-index:2}
.lt-why-card:hover{transform:translateY(-8px);box-shadow:0 26px 50px rgba(11,35,63,.12);border-color:transparent}
.lt-why-card:hover::after{width:100%}
.lt-why-visual img{animation:ltFloat 6s ease-in-out infinite;transition:transform .5s cubic-bezier(.2,.7,.2,1)}
.lt-why-card:nth-child(2n) .lt-why-visual img{animation-delay:-2s}
.lt-why-card:nth-child(3n) .lt-why-visual img{animation-delay:-4s}
.lt-why-card:hover .lt-why-visual img{transform:scale(1.07)}
@keyframes ltFloat{0%,100%{translate:0 0}50%{translate:0 -8px}}

/* ---------- WHAT WE HELP WITH: numbered list ----------
   Row container class: lt-help-item   (+ lt-acc-coral on rows 2,3,6) */
.lt-help-item{position:relative}
.lt-help-item::before{content:"";position:absolute;left:0;top:-1px;height:2px;width:0;background:var(--lt-teal);
  transition:width .45s cubic-bezier(.2,.7,.2,1)}
.lt-help-item.lt-acc-coral::before{background:var(--lt-coral)}
.lt-help-item:hover::before{width:100%}
.lt-help-item .elementor-heading-title{transition:color .2s}
.lt-help-item:hover .elementor-heading-title{color:var(--lt-teal-d)}

/* ---------- Client logos (Image widget class: lt-logo) ---------- */
.lt-logo img{mix-blend-mode:multiply;transition:transform .2s}
.lt-logo img:hover{transform:scale(1.05)}

/* ---------- Form: chip-style checkboxes & radios (Form widget class: lt-form) ---------- */
.lt-form .elementor-field-type-checkbox .elementor-field-subgroup,
.lt-form .elementor-field-type-radio .elementor-field-subgroup{display:flex;flex-wrap:wrap;gap:10px}
.lt-form .elementor-field-option{margin:0!important}
.lt-form .elementor-field-option input{position:absolute;opacity:0;width:1px;height:1px}
.lt-form .elementor-field-option label{display:inline-block;padding:9px 16px;border-radius:999px;border:1.5px solid var(--lt-line);
  font-size:14px;font-weight:500;color:var(--lt-navy);cursor:pointer;transition:all .15s;background:#FBFDFE}
.lt-form .elementor-field-option label:hover{border-color:var(--lt-teal)}
.lt-form .elementor-field-type-checkbox input:checked+label{background:var(--lt-navy);border-color:var(--lt-navy);color:#fff}
.lt-form .elementor-field-type-radio input:checked+label{background:var(--lt-teal);border-color:var(--lt-teal);color:#fff}
.lt-form .elementor-field-option input:focus-visible+label{outline:3px solid var(--lt-coral);outline-offset:2px}

/* ---------- Homepage-style buttons (add class lt-btn-glow to any Button widget) ---------- */
.lt-btn-glow .elementor-button{box-shadow:0 8px 22px rgba(0,162,174,.35);transition:transform .2s,box-shadow .2s,background-color .2s}
.lt-btn-glow .elementor-button:hover{transform:translateY(-2px);box-shadow:0 12px 28px rgba(0,162,174,.45)}
.lt-btn-glow-soft .elementor-button{box-shadow:0 8px 22px rgba(0,162,174,.18)}
.lt-btn-glow-cyan .elementor-button{box-shadow:0 8px 26px rgba(0,192,207,.4)}

/* ---------- Dark bands (container class lt-dark-band): homepage shapes ---------- */
.lt-dark-band{position:relative;overflow:hidden}
.lt-dark-band::before{content:"";position:absolute;right:-90px;top:-120px;width:420px;height:360px;border-radius:90px;
  background:linear-gradient(140deg,rgba(0,192,207,.18),rgba(0,192,207,0) 70%);pointer-events:none}
.lt-dark-band::after{content:"";position:absolute;left:6%;bottom:-110px;width:190px;height:190px;border-radius:50%;
  border:38px solid rgba(37,84,214,.22);pointer-events:none}
.lt-dark-band>.e-con-inner,.lt-dark-band>.e-con{position:relative;z-index:1}

/* ---------- Mobile: Why cards as swipe row if you keep a Grid instead of the Nested Carousel ---------- */
@media (max-width:767px){
  .lt-why-grid{display:flex!important;overflow-x:auto;scroll-snap-type:x mandatory;gap:14px;scrollbar-width:none}
  .lt-why-grid::-webkit-scrollbar{display:none}
  .lt-why-grid>.lt-why-card{flex:0 0 82%!important;scroll-snap-align:center}
}

@media (prefers-reduced-motion:reduce){
  .lt-why-visual img{animation:none}
  .lt-why-card,.lt-why-card:hover{transform:none}
}

/* ===== Page-level styles used by the template (classes set in Advanced → CSS Classes) ===== */
html{scroll-behavior:smooth;scroll-padding-top:84px}
.elementor-widget-text-editor p:last-child{margin-bottom:0}
.lt-maxw-540{max-width:540px}.lt-maxw-440{max-width:440px}.lt-maxw-680,.lt-maxw-720,.lt-maxw-980,.lt-maxw-1080{margin-left:auto!important;margin-right:auto!important}
.lt-maxw-680{max-width:680px}.lt-maxw-720{max-width:720px}.lt-maxw-980{max-width:980px}.lt-maxw-1080{max-width:1080px}
/* Header */
.elementor .lt-brand img.lt-event-logo{height:32px;width:auto;max-width:none;display:block}
@media (max-width:767px){.elementor .lt-brand img.lt-event-logo{height:20px;max-width:110px;object-fit:contain}.lt-brand{min-width:0;flex-shrink:1;overflow:hidden}.lt-lang a{padding:5px 8px}}
.lt-mobile-cta.e-con{--width:auto;width:auto}
.lt-header>.e-con-inner>.e-con{--width:auto;width:auto;flex:0 1 auto}
.lt-navlink .elementor-heading-title a{position:relative;padding:6px 0;color:inherit}
.lt-navlink .elementor-heading-title a::after{content:"";position:absolute;left:0;bottom:0;height:2px;width:0;background:var(--lt-teal);transition:width .2s}
.lt-navlink .elementor-heading-title a:hover{color:var(--lt-teal)}
.lt-navlink .elementor-heading-title a:hover::after{width:100%}
.lt-lang{display:flex;gap:2px;border:1px solid var(--lt-line);border-radius:999px;padding:3px;font:600 13px/1 "Open Sans",sans-serif;background:#fff}
.lt-lang a{padding:6px 11px;border-radius:999px;color:#7A8898}
.lt-lang a.is-active{background:var(--lt-teal);color:#fff}
/* Hero */
.lt-hero-title .elementor-heading-title span{display:block;color:var(--lt-coral)}
.lt-closing-title .elementor-heading-title span{color:var(--lt-coral)}
.lt-kv-logos{background:#fff;border-radius:12px;padding:10px 14px;box-shadow:0 10px 30px rgba(11,35,63,.07)}
.elementor .lt-kv-logos img{height:26px;width:auto;max-width:none;display:block}
@media (max-width:767px){.lt-kv-badge{position:relative!important;inset:auto!important;margin:-36px 16px 0!important;width:auto!important;max-width:none!important}}
.elementor .lt-avatar img{width:52px!important;height:52px!important;border-radius:50%;object-fit:cover}
.lt-bar-item+.lt-bar-item{border-left:1px solid var(--lt-line)}
@media (max-width:1024px){.lt-bar-item:nth-child(3){border-left:0}.lt-bar-item:nth-child(n+3){border-top:1px solid var(--lt-line)}}
@media (max-width:767px){.lt-bar-item+.lt-bar-item{border-left:0;border-top:1px solid var(--lt-line)}}
.lt-cert img{height:58px!important;width:auto!important}
@media (max-width:767px){.lt-cert img{height:46px!important}}
/* Who we are: number badges */
.lt-num .elementor-heading-title{width:38px;height:38px;border-radius:50%;background:var(--lt-aqua);display:grid;place-items:center}
.lt-num-coral .elementor-heading-title{background:#FDEEEE;color:var(--lt-coral)!important}
.lt-point{transition:box-shadow .2s}.lt-point:hover{box-shadow:0 16px 36px rgba(11,35,63,.1)!important}
/* Stats, testimonials */
.lt-stat .elementor-heading-title em{font-style:normal;color:var(--lt-coral)}
.lt-grow{flex-grow:1}
/* Wael */
.lt-wael-photo{position:relative}
.lt-wael-photo::before{content:"";position:absolute;width:90px;height:90px;left:-24px;top:-24px;border-radius:50%;border:10px solid var(--lt-coral);opacity:.15;z-index:0}
.lt-wael-photo img{object-position:center 20%}
/* Footer links */
.lt-footer-links a{color:var(--lt-navy)}.lt-footer-links a:hover{color:var(--lt-teal)}
/* Button on dark band */
.lt-btn-light .elementor-button{box-shadow:0 0 20px rgba(0,192,207,.22)}
